import React, { useState } from 'react';
import { Package, Tag, Layers, Sparkles, Image as ImageIcon, ExternalLink } from 'lucide-react';

/**
 * ProductPreviewCard - Right sidebar component showing live product preview
 * Features:
 * - Product image with fallback
 * - Product name, brand, category badges
 * - Auto-generated indicators
 * - Integrated inline image search panel
 */
const ProductPreviewCard = ({ 
  productData, 
  isDescriptionAutoGenerated,
  hasAutoDetectedAttributes,
  onImageSelect 
}) => {
  const [showImageSearch, setShowImageSearch] = useState(false);

  const {
    productName = 'Untitled Product',
    brandName = '',
    category = '',
    subcategory = '',
    mainImage = '',
    price = 0,
  } = productData;

  // Generate search query for image search
  const imageSearchQuery = `${brandName} ${productName} ${category} ${subcategory} makeup cosmetics`.trim();

  return (
    <div className="bg-white rounded-lg shadow-sm border border-gray-200 overflow-hidden">
      {/* Header */}
      <div className="bg-gradient-to-r from-purple-50 to-pink-50 px-4 py-3 border-b border-gray-200">
        <div className="flex items-center gap-2">
          <Package className="w-5 h-5 text-purple-600" />
          <h3 className="font-semibold text-gray-800">Product Preview</h3>
        </div>
      </div>

      {/* Product Image */}
      <div className="relative aspect-square bg-gray-100">
        {mainImage ? (
          <img
            src={mainImage}
            alt={productName}
            className="w-full h-full object-cover"
          />
        ) : (
          <div className="absolute inset-0 flex flex-col items-center justify-center text-gray-400">
            <ImageIcon className="w-16 h-16 mb-2" />
            <p className="text-sm">No image uploaded</p>
          </div>
        )}

        {/* Open Image Search in New Tab Button */}
        <button
          onClick={() => {
            const query = [productData?.brand, productData?.name, productData?.category].filter(Boolean).join(' ') || 'cosmetics product';
            window.open(`https://www.google.com/search?tbm=isch&q=${encodeURIComponent(query)}`, '_blank', 'noopener,noreferrer');
          }}
          className="absolute top-3 right-3 p-2 rounded-lg shadow-lg bg-white/90 text-gray-700 hover:bg-white hover:text-[#E11D48] transition-all cursor-pointer"
          title="Open image search in new browser tab"
        >
          <ExternalLink className="w-4 h-4" />
        </button>

        {/* Auto-generated badge */}
        {(isDescriptionAutoGenerated || hasAutoDetectedAttributes) && (
          <div className="absolute bottom-3 left-3">
            <div className="bg-emerald-500 text-white px-3 py-1 rounded-full text-xs font-medium flex items-center gap-1 shadow-lg">
              <Sparkles className="w-3 h-3" />
              <span>AI Enhanced</span>
            </div>
          </div>
        )}
      </div>

      {/* Product Details */}
      <div className="p-4 space-y-3">
        {/* Product Name */}
        <div>
          <h4 className="font-semibold text-lg text-gray-900 line-clamp-2">
            {productName}
          </h4>
          {brandName && (
            <p className="text-sm text-gray-600 mt-1">{brandName}</p>
          )}
        </div>

        {/* Badges */}
        <div className="flex flex-wrap gap-2">
          {category && (
            <span className="inline-flex items-center gap-1 px-2.5 py-1 bg-blue-50 text-blue-700 rounded-full text-xs font-medium border border-blue-200">
              <Layers className="w-3 h-3" />
              {category}
            </span>
          )}
          {subcategory && (
            <span className="inline-flex items-center gap-1 px-2.5 py-1 bg-purple-50 text-purple-700 rounded-full text-xs font-medium border border-purple-200">
              <Tag className="w-3 h-3" />
              {subcategory}
            </span>
          )}
        </div>

        {/* Price Preview */}
        {price > 0 && (
          <div className="pt-3 border-t border-gray-200">
            <div className="flex items-baseline gap-2">
              <span className="text-2xl font-bold text-gray-900">
                ₹{price.toFixed(2)}
              </span>
              <span className="text-sm text-gray-500">Base Price</span>
            </div>
          </div>
        )}

        {/* AI Features Indicators */}
        {(isDescriptionAutoGenerated || hasAutoDetectedAttributes) && (
          <div className="pt-3 border-t border-gray-200">
            <p className="text-xs font-medium text-gray-700 mb-2">AI Features Active:</p>
            <div className="space-y-1">
              {isDescriptionAutoGenerated && (
                <div className="flex items-center gap-2 text-xs text-emerald-600">
                  <div className="w-1.5 h-1.5 bg-emerald-500 rounded-full"></div>
                  <span>Auto-generated description</span>
                </div>
              )}
              {hasAutoDetectedAttributes && (
                <div className="flex items-center gap-2 text-xs text-emerald-600">
                  <div className="w-1.5 h-1.5 bg-emerald-500 rounded-full"></div>
                  <span>Auto-detected variant attributes</span>
                </div>
              )}
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default ProductPreviewCard;
